"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoVaults } from "hooks/morpho";
import { useMemo } from "react";
import { ArrowUpRight } from "react-feather";
import { Link } from "react-router-dom";
import { Button, Flex, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useEarnContext } from "../ContextProvider";
const CardWrapper = styled(Flex, {
  flexDirection: "column",
  width: "100%",
  gap: "$spacing16"
});
const Card = styled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  p: "$spacing24",
  gap: "$spacing24"
});
const LabelText = styled(Text, {
  color: "$neutral2",
  variant: "body2",
  $sm: {
    variant: "body3"
  }
});
const ValueText = styled(LabelText, {
  color: "$neutral1"
});
const Divider = styled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3"
});
const ActionButton = styled(Button, {
  borderRadius: "$roundedFull",
  py: "$spacing12"
});
const DataRow = ({
  label,
  value,
  subValue,
  icon
}) => <Flex row justifyContent="space-between" alignItems="center" width="100%">
    <LabelText color="$neutral2">{label}</LabelText>
    <Flex row alignItems="flex-end" gap={"$spacing8"}>
      <Flex flexDirection="row" alignItems="center" gap="$gap8">
        {icon}
        <ValueText color="$neutral1">{value}</ValueText>
      </Flex>
      {subValue && <Flex
  $sm={{ display: "none" }}
  backgroundColor="$surface3"
  paddingHorizontal="$spacing8"
  paddingVertical="$spacing2"
  borderRadius="$roundedFull"
>
          <Text variant="body4" color="$neutral2">
            {subValue}
          </Text>
        </Flex>}
    </Flex>
  </Flex>;
const TOKEN_PRICES_USD = {
  USDC: 1,
  WETH: 3500,
  ETH: 3500
};
function getTokenPriceUsd(symbol) {
  return TOKEN_PRICES_USD[symbol.toUpperCase()] ?? 1;
}
function transformMorphoVaultToVaultData(morphoVault) {
  const totalAssetsNumber = Number(morphoVault.totalAssetsFormatted);
  const totalIdleNumber = Number(morphoVault.totalIdleFormatted);
  const tokenPriceUsd = getTokenPriceUsd(morphoVault.asset.symbol);
  const depositsUsd = totalAssetsNumber * tokenPriceUsd;
  const liquidityUsd = totalIdleNumber * tokenPriceUsd;
  return {
    id: morphoVault.address,
    address: morphoVault.address,
    name: morphoVault.name,
    symbol: morphoVault.symbol,
    token: {
      id: morphoVault.asset.address,
      address: morphoVault.asset.address,
      symbol: morphoVault.asset.symbol,
      name: morphoVault.asset.name,
      decimals: morphoVault.asset.decimals
    },
    deposits: totalAssetsNumber,
    depositsUsd,
    liquidity: totalIdleNumber,
    liquidityUsd,
    exposure: 0,
    apy: 0,
    sharePrice: Number(morphoVault.sharePriceFormatted),
    feePercent: morphoVault.feePercent,
    isVerified: true
  };
}
export default function EarnCard() {
  const { formatFiatPrice } = useFormatter();
  const colors = useSporeColors();
  const { openTransaction, activeTab } = useEarnContext();
  const chainId = UniverseChainId.Mainnet;
  const { data: morphoVaults, isLoading } = useMorphoVaults(chainId);
  const vaults = useMemo(() => {
    if (!morphoVaults) return [];
    return morphoVaults.map(transformMorphoVaultToVaultData);
  }, [morphoVaults]);
  if (isLoading) {
    return <CardWrapper>
        <Flex centered py="$spacing24">
          <SpinningLoader size={24} />
        </Flex>
      </CardWrapper>;
  }
  return <CardWrapper>
      {vaults.map((vault) => <Card key={vault.id}>
          {
    /* Header */
  }
          <Flex row justifyContent="space-between" alignItems="center" width="100%">
            <Link className="text-decoration-none" to={`/earn/vault?address=${vault.address}`}>
              <Flex row alignItems="center" gap="$gap12">
                <PortfolioLogo
    chainId={chainId}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name}
    images={[getTokenLogoUrl(vault.token.address)]}
    size={32}
  />
                <Flex row alignItems="center" gap="$gap8">
                  <LabelText>{vault.name}</LabelText>
                  <ArrowUpRight size={18} color={colors.neutral2.val} />
                </Flex>
              </Flex>
            </Link>
            <Flex alignItems="center" gap="$gap4">
              <ValueText color={"$neutral1"}>{vault.apy.toFixed(2)}%</ValueText>
            </Flex>
          </Flex>

          <Divider />

          {
    /* Stats */
  }
          <Flex flexDirection="column" gap="$gap16">
            <DataRow
    label="Total Deposits"
    value={formatFiatPrice({ price: vault.depositsUsd, type: NumberType.FiatTokenStats })}
    subValue={`${vault.deposits.toFixed(4)} ${vault.token.symbol}`}
  />
            <DataRow
    label="Liquidity"
    value={formatFiatPrice({ price: vault.liquidityUsd, type: NumberType.FiatTokenStats })}
    subValue={`${vault.liquidity.toFixed(4)} ${vault.token.symbol}`}
  />
            <DataRow label="Fee" value={`${vault.feePercent.toFixed(1)}%`} />
            <DataRow
    label="Asset"
    value={vault.token.symbol}
    icon={<PortfolioLogo
      chainId={chainId}
      tokenSymbol={vault.token.symbol}
      tokenName={vault.token.name}
      images={[getTokenLogoUrl(vault.token.address)]}
      size={16}
    />}
  />
          </Flex>

          <Divider />

          <Flex flexDirection="row" gap="$spacing18" justifyContent="space-between">
            <ActionButton onPress={() => openTransaction(vault, "deposit")}>Deposit</ActionButton>
            {activeTab === "positions" && <ActionButton onPress={() => openTransaction(vault, "withdraw")}>Withdraw</ActionButton>}
          </Flex>
        </Card>)}
    </CardWrapper>;
}
